mapper.select:
        select
        wrmr.*
        FROM wms_remnant_material_returnable wrmr
        left join wms_material_returnable wmr on wrmr.material_returnable_id = wmr.id
        left join wms_outbound wo on wmr.outbound_id = wo.id
        where
        wrmr.bool_delete_enum = 0
        and  wrmr.returnable_mete != 0
        
            and wo.outbound_type_selection = #{outboundTypeSelection}
        
        
            and wrmr.basic_class = #{basicClass}
        
        
            and wrmr.classify_id = #{classifyId}
        



        
            and wrmr.warehouse_id = #{warehouseId}
        
        
            AND wrmr.specification like CONCAT('%', #{specification},'%')
        
        
            AND wrmr.length = #{length}
        
        
            AND wrmr.width = #{width}
        
        
            AND wrmr.theory_thickness = #{theoryThickness}
        
        
            AND wrmr.thickness = #{thickness}
        
        
            AND wrmr.project_id = #{projectId}
        
        
            AND wrmr.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND wrmr.color like CONCAT('%', #{color},'%')
        
        
            AND wrmr.brand like CONCAT('%', #{brand},'%')
        
        
            and wrmr.workshop_id=#{workshopId}
        
        
            and wrmr.classify_id in
            
                #{item}
            
        
        
            and wrmr.classify_id = #{classifyId}
        
        
            and wrmr.returnable_mete >=#{mete}
        
        
            and wrmr.bool_party_a =#{boolPartyA}
        
        
            and wrmr.area_batch_id = #{areaBatchId}
        
        
            and wrmr.recipient_id = #{recipientId}
        
        
            
                -- 开始时间: 数据 大于 条件
                and wrmr.create_time > #{createTime[0]}
            
            
                -- 结束时间: 数据 小于 条件
                and wrmr.create_time < #{createTime[1]}
